bots = json.load(open(BOTS))
assert isinstance(bots, list)
have = {b['slug'] for b in bots}
urls = {b.get('url','').rstrip('/') for b in bots}

SEL = json.load(open('/root/.hermes/cache/scratch/sel45.json'))
assert len(SEL) == len(E)
added = 0
for e, s in zip(E, SEL):
    if e['slug'] in have:
        print('SKIP dup slug', e['slug']); continue
    entry = {
        'slug': e['slug'],
        'name': e['name'],
        'builder': {'name': e['b'], 'x': e['x']},
        'tagline': e['tag'],
        'description': e['desc'],
        'category': e['cat'],
        'url': s['url'],
        'addedAt': DAY,
        'status': 'published',
    }
    if e['src']:
        entry['source'] = e['src']
    assert len(entry['tagline']) <= 140, (entry['slug'], len(entry['tagline']))
    bots.append(entry)
    have.add(e['slug']); urls.add(entry['url'].rstrip('/'))
    added += 1

json.dump(bots, open(BOTS,'w'), indent=1, ensure_ascii=False)
print('added', added, 'total', len(bots))
